TL=[
(29,0,'Tóm tắt đoạn A trong hai câu.', ['Đ5'], 'Mặt Trời đi kiệu do tốp già và tốp trẻ luân phiên khiêng. Tốp già đi nhanh, tốp trẻ la cà nên bản kể dùng hai hành trình ấy để cắt nghĩa ngày ngắn và ngày dài.', ['Nêu nhân vật và hành trình.', 'Giữ đúng quan hệ hai tốp với hai kết quả; không bình luận thêm.']),
(30,0,'Lí giải vì sao chi tiết khiêng kiệu có thể làm thiên thể trở nên gần gũi.', ['Đ9'], 'Kiệu và người khiêng thuộc sinh hoạt có thể quan sát. Khi Mặt Trời cũng đi kiệu, hành trình trên bầu trời được hình dung qua hành động quen thuộc. Tính cách của hai tốp còn tạo một nguyên nhân hóm hỉnh cho sự khác nhau về độ dài ngày.', ['Chỉ ra cái quen thuộc.', 'Giải thích nhân cách hoá và tác dụng cắt nghĩa.']),
(31,1,'Phân tích vai trò của Thần Mưa trong cốt truyện B.', ['Đ6'], 'Thần thực hiện công việc cấp nước nên là trung tâm của mạch giải thích mưa. Tật hay quên dẫn đến tình thế nước phân phối không đều. Công việc quá nặng dẫn tới việc tuyển thêm rồng, vì vậy đặc điểm của thần tham gia trực tiếp vào sự phát triển cốt truyện.', ['Quyền năng và nhiệm vụ.', 'Hạn chế gắn với diễn biến; tránh chỉ kể tật xấu.']),
(32,1,'Xác định chủ đề B và nêu hai căn cứ.', ['Đ7'], 'Đoạn kể cắt nghĩa mưa, hạn, lụt qua việc phân phối nước và hình dung cách có thêm rồng giúp sức. Căn cứ là hành động hút nước, phun mưa của thần và cuộc thi vượt sóng để hoá rồng. Nhu cầu nước cho cày cấy giúp lí giải vì sao vấn đề được coi trọng.', ['Chủ đề bao quát.', 'Hai bằng chứng và quan hệ của chúng với chủ đề.']),
(33,1,'Dùng bối cảnh sinh hoạt ở B để giải thích vì sao cần mưa điều hoà.', ['Đ12'], 'Đoạn nhắc nước cho uống và cày cấy, cho thấy đời sống phụ thuộc vào nguồn nước. Thiếu nước dẫn đến hạn, quá nhiều lại gây lụt. Vì vậy, điều người trồng trọt cần không chỉ là có mưa mà là mưa được phân phối phù hợp. Công việc của thần gắn với mối quan tâm ấy.', ['Đọc dấu vết nông nghiệp.', 'Giải thích nhu cầu nước vừa đủ, không thêm số liệu.']),
(34,2,'Phân biệt đề tài và chủ đề của C.', ['Đ3','Đ7'], 'Đề tài là cây lúa và công việc thu hoạch, chế biến trong đời sống nông nghiệp. Chủ đề là cách người xưa lí giải sự thay đổi từ nguồn lương thực được trao sẵn sang công sức làm ra gạo, cùng thái độ coi trọng cây lúa thể hiện qua tục cúng sau mùa gặt. Đề tài gọi phạm vi, chủ đề nêu vấn đề và cách nhìn.', ['Không chỉ lặp hai định nghĩa.', 'Áp dụng được vào chính đoạn C.']),
(35,2,'Tách một nhận xét phân tích và một nhận xét đánh giá từ chi tiết cô gái dùng chổi.', ['Đ9','Đ13'], 'Phân tích: hành động đập chổi là biến cố khiến thần giận và lúa không còn tự về. Đánh giá: dùng một vật sinh hoạt nhỏ để dẫn đến thay đổi lớn là cách kể dễ nhớ, giúp lời giải thích công việc nông nghiệp có tình huống cụ thể. Không cần khen chung rằng mọi yếu tố đều tuyệt vời.', ['Chỉ ra chức năng chi tiết.', 'Nhận xét hiệu quả dựa trên chức năng đã nêu.']),
(36,2,'Nêu tác động của C đến cách em ứng xử với bữa ăn. Viết một đoạn 4–5 câu.', ['Đ10','Đ11'], 'Đoạn kể khiến em nghĩ tới công sức để có một bữa cơm. Khi lúa không còn tự về, con người phải gặt và xay giã. Em sẽ lấy thức ăn vừa sức, không bỏ thừa chỉ vì lấy quá nhiều. Nếu còn đồ ăn dùng được, em sẽ bảo quản đúng cách theo hướng dẫn của gia đình.', ['Có chi tiết làm căn cứ.', 'Có hành động vừa sức, không chỉ nói biết ơn.']),
(37,3,'Nêu tác dụng của cách kể ngôi thứ ba trong D; không mặc định toàn tri.', ['Đ8'], 'Người kể gọi tên hai anh em, thuật việc tạo loài rồi chuyển sang hành động sửa và trao lửa. Cách kể cho phép nối các khâu của công việc và cho người đọc thấy thiếu sót được giải quyết thế nào. Đoạn chưa cần gọi người kể là toàn tri, vì không có bằng chứng rõ về việc biết mọi nội tâm và mọi nơi.', ['Dấu hiệu ngôi kể.', 'Tác dụng đúng với phạm vi đoạn; không dùng lời khen khách quan tự động.']),
(38,3,'So sánh D với C về cách dùng hành động đời thường để kể chuyện phi thường.', ['Đ9','Đ13'], 'C dùng việc về nhà, cáu giận và gặt lúa; D dùng nặn bằng đất nước và sửa hình. Cả hai tạo điểm tựa quen thuộc để hình dung nguồn sống hoặc nguồn gốc. Khác nhau ở vấn đề chính: C hướng vào lúa và công việc thu hoạch, D hướng vào con người và khả năng sống. So sánh cần giữ cả nét chung lẫn nét riêng.', ['Hai điểm tựa từ hai đoạn.', 'Nét chung và nét riêng; không xếp hạng hơn kém vô căn cứ.']),
(39,3,'Em đánh giá thế nào về hành động Prô-mê-tê sửa thiếu sót thay vì bỏ đi? Viết 4–5 câu.', ['Đ13'], 'Em đánh giá cao việc thần hành động sau khi nhận ra phần con người bị bỏ sót. Sửa dáng và trao lửa cho thấy sự giúp đỡ có kết quả cụ thể. Trong việc chung, phát hiện lỗi chỉ là bước đầu; tìm cách sửa mới giúp giảm hậu quả. Dù vậy, đây là liên hệ từ hành động nhân vật, không phải yêu cầu một người phải tự làm thay mọi việc cho người khác.', ['Quan điểm rõ.', 'Có bằng chứng và lí lẽ; liên hệ vừa mức.']),
(40,0,'Có nên dùng A thay kiến thức khoa học về độ dài ngày? Trả lời có lí lẽ, đồng thời nêu một giá trị của đoạn.', ['Đ12','Đ13'], 'Không nên dùng lời kể khiêng kiệu thay cho kiến thức thiên văn. Nó thể hiện cách hình dung bằng trí tưởng tượng chứ không phải kết quả đo đạc, kiểm chứng. Tuy nhiên, đoạn vẫn có giá trị văn hoá vì cho thấy người xưa đưa kinh nghiệm sinh hoạt vào việc tìm hiểu vũ trụ. Phân biệt hai cách đọc giúp vừa học khoa học vừa trân trọng truyện kể.', ['Phân biệt khoa học với văn học.', 'Ghi nhận giá trị văn hoá, không phủ nhận bằng lời chê đơn giản.'])
]
BANK=dict(passages=PASSAGES, questions=MC, short=[dict(number=n,group=g,stem=s,indicators=cb,sample=a,criteria=c) for n,g,s,cb,a,c in TL])
